1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const SURCHARGED_ENCHANTMENT_THRESHOLD = 5;
45	const ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	/**
51	 * "All amounts are rounded to whole G in the MHPCO's favour." One rule, two
52	 * directions: the MHPCO collects premiums, so those round UP; it disburses
53	 * payouts, so those round DOWN. The pair is named rather than written as bare
54	 * Math.ceil / Math.floor at the call sites so that the shared rule — and the
55	 * fact that the two directions are the same rule, not two ad-hoc conveniences —
56	 * survives a reader who only ever sees one of them.
57	 *
58	 * WHERE these are applied is load-bearing and is decided at the call site, not
59	 * here. In particular the claim path rounds the amount claimed BEFORE it is
60	 * clamped against the cap, so that the cap arithmetic runs in whole gold;
61	 * rounding the returned payout instead would leave a fraction in the remaining
62	 * cap. Intermediates — the halved damage amount, the per-damage deductible
63	 * subtraction — stay fractional per the spec.
64	 */
65	const roundedInFavourOfMHPCO = {
66	  collected: Math.ceil,
67	  disbursed: Math.floor,
68	};
69	
70	const BASE_PREMIUMS: Record<string, number> = {
71	  sword: 100,
72	  amulet: 60,
73	  staff: 80,
74	  potion: 40,
75	  rune: 25,
76	  moonstone: 25,
77	};
78	
79	const INSURANCE_VALUES: Record<string, number> = {
80	  sword: 1000,
81	  amulet: 600,
82	  rune: 250,
83	};
84	
85	const DEDUCTIBLE_PER_DAMAGE = 100;
86	const HALVED_ENCHANTMENT_THRESHOLD = 8;
87	const HALVED_REIMBURSEMENT = 0.5;
88	const FULL_REIMBURSEMENT = 1;
89	const CAP_MULTIPLIER = 2;
90	
91	const ALIKE_BLOCK_SIZE = 3;
92	const ALIKE_BLOCK_PREMIUM = 60;
93	
94	const sum = (amounts: number[]): number =>
95	  amounts.reduce((total, amount) => total + amount, 0);
96	
97	type AlikeGroup = [type: string, count: number];
98	
99	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
100	  const countByType = new Map<string, number>();
101	
102	  for (const item of items) {
103	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
104	  }
105	
106	  return [...countByType];
107	};
108	
109	/**
110	 * Rejection for a value the MHPCO requires but does not have. The two rate
111	 * tables are keyed by item type, and an item type absent from either has no
112	 * answer to give — so the lookup rejects rather than handing back `undefined`
113	 * for the arithmetic downstream to turn into NaN.
114	 *
115	 * Deliberately narrow: this covers a MISSING value only. A value that is
116	 * present but unacceptable — a damage amount of -200, say — is a different
117	 * shape of rejection and is not forced through here.
118	 */
119	const required = <T>(value: T | undefined, message: string): T => {
120	  if (value === undefined) throw new Error(message);
121	
122	  return value;
123	};
124	
125	const uninsuredTypeMessage = (type: string): string =>
126	  `The MHPCO does not insure items of type "${type}".`;
127	
128	const basePremiumOfType = (type: string): number =>
129	  required(BASE_PREMIUMS[type], uninsuredTypeMessage(type));
130	
131	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
132	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
133	
134	  return count * basePremiumOfType(type);
135	};
136	
137	/**
138	 * The policy base premium: the sum of the item base premiums, with the
139	 * alike-block discount applied. Policy-scope modifiers are percentages OF
140	 * THIS amount — never of a total that already includes item surcharges.
141	 */
142	const policyBasePremiumOf = (items: Item[]): number =>
143	  sum(groupAlikeItems(items).map(basePremiumOfGroup));
144	
145	/**
146	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
147	 * premium, independent of the policy base and of the alike-block discount.
148	 */
149	const isCursed = (item: Item): boolean => item.cursed === true;
150	
151	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
152	
153	const carriesEnchantmentSurcharge = (item: Item): boolean =>
154	  enchantmentOf(item) >= SURCHARGED_ENCHANTMENT_THRESHOLD;
155	
156	const itemSurchargeRateOf = (item: Item): number =>
157	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
158	  (carriesEnchantmentSurcharge(item) ? ENCHANTMENT_SURCHARGE : 0);
159	
160	const itemSurchargesOf = (items: Item[]): number =>
161	  items.reduce(
162	    (total, item) =>
163	      total + basePremiumOfType(item.type) * itemSurchargeRateOf(item),
164	    0,
165	  );
166	
167	/**
168	 * Policy-scope modifiers: each is a percentage of the policy base premium.
169	 * Surcharges and discounts are netted into a single rate, so the policy base is
170	 * multiplied exactly once — this keeps the result free of the rounding drift
171	 * that separate discount and surcharge terms would introduce. The netted rate
172	 * (and hence the returned amount) is negative when the discounts outweigh the
173	 * surcharges.
174	 */
175	const isLongStanding = (customer: Customer): boolean =>
176	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
177	
178	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
179	  FIRST_INSURANCE_SURCHARGE -
180	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
181	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
182	
183	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
184	  policyBase * policyModifierRateOf(policy);
185	
186	const quotePremium = (items: Item[], policy: Policy): number => {
187	  const policyBase = policyBasePremiumOf(items);
188	  const premium =
189	    policyBase +
190	    itemSurchargesOf(items) +
191	    policyModifiersOn(policyBase, policy) +
192	    PROCESSING_FEE;
193	
194	  return roundedInFavourOfMHPCO.collected(premium);
195	};
196	
197	/**
198	 * Whether any step precedes this one. A quote is a follow-up contract when the
199	 * customer already holds one, and today every step is a quote — so "has a
200	 * predecessor" and "is a follow-up contract" coincide.
201	 *
202	 * They stop coinciding once claim steps exist: a claim at index 0 would make
203	 * the quote at index 1 look like a follow-up. At that point the caller must
204	 * count preceding QUOTE steps instead of asking this. The name is deliberately
205	 * about position, not contracts, so that the substitution is a visible change
206	 * at the call site rather than a silent redefinition here.
207	 */
208	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
209	
210	const insuredValueOfType = (type: string): number =>
211	  required(INSURANCE_VALUES[type], uninsuredTypeMessage(type));
212	
213	const insuranceSumOf = (items: Item[]): number =>
214	  sum(items.map(({ type }) => insuredValueOfType(type)));
215	
216	const isReimbursedByHalf = (item: Item): boolean =>
217	  enchantmentOf(item) >= HALVED_ENCHANTMENT_THRESHOLD;
218	
219	/**
220	 * The share of a damage amount that is reimbursed, before the deductible.
221	 *
222	 * The specification's dragon-material rule ("damage to items made of dragon
223	 * material is fully reimbursed") is deliberately ABSENT here, and `Item` has no
224	 * `material` field. The rule is unobservable given the other rules:
225	 *
226	 * - Full reimbursement is already FULL_REIMBURSEMENT, the default rate, so on
227	 *   items below the halving threshold a dragon clause would compute what this
228	 *   function computes anyway.
229	 * - The only inputs where the two clauses disagree are items with enchantment
230	 *   >= HALVED_ENCHANTMENT_THRESHOLD, and there the spec awards the conflict to
231	 *   halving ("both clauses apply; the 50 % rule wins").
232	 *
233	 * So no input distinguishes an implemented dragon clause from this one. The
234	 * spec's own examples confirm it: a steel sword and a dragon sword at
235	 * enchantment 9 with 1000 G damage both pay out 400 G. Implementing it would
236	 * add an unreachable branch and a field nothing reads.
237	 *
238	 * This stops holding the moment dragon material gains an effect OUTSIDE the
239	 * reimbursement rate — a different deductible, or an exemption from the payout
240	 * cap. Such a rule would need a real `material` field and a real branch.
241	 */
242	const reimbursementRateFor = (item: Item): number =>
243	  isReimbursedByHalf(item) ? HALVED_REIMBURSEMENT : FULL_REIMBURSEMENT;
244	
245	/**
246	 * The insured item a damage entry refers to. A damage naming a type this policy
247	 * does not cover is rejected here — distinctly from `uninsuredTypeMessage`,
248	 * which says the MHPCO will not insure the type at all. An amulet is perfectly
249	 * insurable; it is just not part of a policy that covers only a sword.
250	 */
251	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
252	  required(
253	    items.find(({ type }) => type === damage.itemType),
254	    `The policy does not cover an item of type "${damage.itemType}".`,
255	  );
256	
257	/**
258	 * A single damage entry settles in two stages, in this order: the reimbursement
259	 * rate applies to the damage amount, and the deductible comes off the result.
260	 * The spec is explicit that the sequencing matters ("the 50 % rule wins, then
261	 * deductible"), so it is spelled out rather than left to operator precedence.
262	 */
263	const payoutForDamage = (damage: Damage, items: Item[]): number => {
264	  const reimbursed =
265	    damage.amount * reimbursementRateFor(insuredItemFor(damage, items));
266	
267	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
268	};
269	
270	/**
271	 * The quote step a claim is filed against. Today this ASSUMES the referenced
272	 * index holds a quote: nothing has forced the assumption to be checked yet, and
273	 * a claim naming a non-quote step fails here with an opaque undefined-property
274	 * error rather than a rejection.
275	 *
276	 * The assumption is isolated in this function on purpose. The pending
277	 * error-handling tests ("a claim for an item not part of the policy", "a claim
278	 * with a damage entry of an unknown item type") are what will force a real
279	 * rejection, and this is the single place that has to change when they do.
280	 */
281	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
282	  steps[claim.policy] as QuoteStep;
283	
284	/**
285	 * The total a claim asks for: every damage entry settled on its own, then
286	 * summed. Unclamped — the payout cap is applied to this total, not per damage.
287	 */
288	const amountClaimed = (incident: Incident, items: Item[]): number =>
289	  incident.damages.reduce(
290	    (total, damage) => total + payoutForDamage(damage, items),
291	    0,
292	  );
293	
294	/**
295	 * Applying the payout cap to a claim: a policy pays at most what is left of its
296	 * cap, and whatever it pays comes off that remainder. Pure, and stated as a
297	 * before/after pair, so the invariant `payout + capAfter === capBefore` is
298	 * visible in one place rather than spread across the caller.
299	 */
300	const chargedAgainstCap = (claimed: number, capBefore: number): ClaimResult => {
301	  const payout = Math.min(claimed, capBefore);
302	
303	  return { payout, remainingCap: capBefore - payout };
304	};
305	
306	/**
307	 * The cap a policy starts with, before any claim has drawn on it.
308	 */
309	const initialCapOf = (policy: QuoteStep): number =>
310	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
311	
312	/**
313	 * Settling a claim DRAWS DOWN the policy's remaining cap: the result depends on
314	 * how much earlier claims already consumed, so the running cap is read from and
315	 * written back to `capRemainingByPolicy`. That state write is this function's
316	 * one effect, and it is deliberately the last statement.
317	 */
318	const settleClaim = (
319	  claim: ClaimStep,
320	  steps: Step[],
321	  capRemainingByPolicy: Map<number, number>,
322	): ClaimResult => {
323	  const policy = policyReferencedBy(claim, steps);
324	  const capBefore =
325	    capRemainingByPolicy.get(claim.policy) ?? initialCapOf(policy);
326	  const settled = chargedAgainstCap(
327	    roundedInFavourOfMHPCO.disbursed(
328	      amountClaimed(claim.incident, policy.items),
329	    ),
330	    capBefore,
331	  );
332	
333	  capRemainingByPolicy.set(claim.policy, settled.remainingCap);
334	
335	  return settled;
336	};
337	
338	const priceQuote = (
339	  quote: QuoteStep,
340	  stepIndex: number,
341	  customer: Customer,
342	): QuoteResult => ({
343	  premium: quotePremium(quote.items, {
344	    customer,
345	    isFollowUpContract: hasPrecedingStep(stepIndex),
346	  }),
347	});
348	
349	/**
350	 * Steps are settled IN ORDER, and that order is load-bearing: a claim's payout
351	 * depends on how much of the policy's cap the claims before it consumed.
352	 */
353	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
354	  const capRemainingByPolicy = new Map<number, number>();
355	
356	  return {
357	    results: scenario.steps.map((step, stepIndex) =>
358	      isQuoteStep(step)
359	        ? priceQuote(step, stepIndex, scenario.customer)
360	        : settleClaim(step, scenario.steps, capRemainingByPolicy),
361	    ),
362	  };
363	};
364

